INSERT INTO products VALUES ('3730', '1', '97139O3000', '97139-O3000 / 97139O3000', '', '46', '7. Giàn lạnh Custin (sedanviet) | 97139-O3000', '7-gian-lanh-custin-sedanviet-97139-o3000', '<h2>Tổng quan về Giàn lạnh Custin</h2>
