INSERT INTO products VALUES ('4551', '1', '8K0260403AB', '8K0-260-403-AB / 8K0260403AB', '', '43', '7. Dàn nóng Q5 (sedanviet) | 8K0-260-403-AB', '7-dan-nong-q5-sedanviet-8k0-260-403-ab', '<h2>Tổng quan về Dàn nóng Q5</h2>
