INSERT INTO products VALUES ('4577', '1', 'GHP961480B', 'GHP96-1480B / GHP961480B', '', '43', '7. Dàn nóng 6 (sedanviet) | GHP96-1480B', '7-dan-nong-6-sedanviet-ghp96-1480b', '<h2>Tổng quan về Dàn nóng 6</h2>
