INSERT INTO products VALUES ('4635', '1', '3W0820411', '3W0820411', '', '43', '7. Dàn nóng BENTLEY Continental Flying Spur (sedanviet) | 3W0820411', '7-dan-nong-bentley-continental-flying-spur-sedanviet-3w0820411', '<h2>Tổng quan về Dàn nóng BENTLEY Continental Flying Spur</h2>
