INSERT INTO products VALUES ('4645', '1', '9923159000', '99231-59000 / 9923159000', '', '43', '7. Dàn nóng Solati (sedanviet) | 99231-59000', '7-dan-nong-solati-sedanviet-99231-59000', '<h2>Tổng quan về Dàn nóng Solati</h2>
