INSERT INTO products VALUES ('4662', '1', 'PL3282', 'PL3282', '', '43', '7. Dàn nóng PACO Seri 3 (sedanviet) | PL3282', '7-dan-nong-paco-seri-3-sedanviet-pl3282', '<h2>Tổng quan về Dàn nóng PACO Seri 3</h2>
