INSERT INTO products VALUES ('4701', '1', '95310M55R00', '95310M55R00', '', '43', '7. Dàn nóng Swift (sedanviet) | 95310M55R00', '7-dan-nong-swift-sedanviet-95310m55r00', '<h2>Tổng quan về Dàn nóng Swift</h2>
