INSERT INTO products VALUES ('4711', '1', '888910D320', '88891-0D320 / 888910D320', '', '43', '7. Ốp giàn nóng Vios (sedanviet) | 88891-0D320', '7-op-gian-nong-vios-sedanviet-88891-0d320', '<h2>Tổng quan về Ốp giàn nóng Vios</h2>
