INSERT INTO products VALUES ('4725', '1', '8710760411', '87107-60411 / 8710760411', '', '43', '7. Dàn nóng LX570 (sedanviet) | 87107-60411', '7-dan-nong-lx570-sedanviet-87107-60411', '<h2>Tổng quan về Dàn nóng LX570</h2>
