INSERT INTO products VALUES ('4733', '1', '31694670', '31694670', '', '43', '7. Dàn nóng XC40 (sedanviet) | 31694670', '7-dan-nong-xc40-sedanviet-31694670', '<h2>Tổng quan về Dàn nóng XC40</h2>
