INSERT INTO products VALUES ('4737', '1', '971384X000', '97138-4X000 / 971384X000', '', '43', '7. Dàn nóng Soluto (sedanviet) | 97138-4X000', '7-dan-nong-soluto-sedanviet-97138-4x000', '<h2>Tổng quan về Dàn nóng Soluto</h2>
