INSERT INTO products VALUES ('4749', '1', 'A00091876', 'A00091876', '', '43', '7. Dàn nóng BAIC Beijing U5 Plus (sedanviet) | A00091876', '7-dan-nong-baic-beijing-u5-plus-sedanviet-a00091876', '<h2>Tổng quan về Dàn nóng BAIC Beijing U5 Plus</h2>
