INSERT INTO products VALUES ('4779', '1', '97606CC100', '97606-CC100 / 97606CC100', '', '43', '7. Dàn nóng Sonet (sedanviet) | 97606-CC100', '7-dan-nong-sonet-sedanviet-97606-cc100', '<h2>Tổng quan về Dàn nóng Sonet</h2>
