INSERT INTO products VALUES ('4817', '1', '1320766500', '13207-66500 / 1320766500', '', '43', '7. Dàn nóng BYD Han (sedanviet) | 13207-66500', '7-dan-nong-byd-han-sedanviet-13207-66500', '<h2>Tổng quan về Dàn nóng BYD Han</h2>
