INSERT INTO products VALUES ('4842', '1', 'P2W919710AA', 'P2W9-19710-AA / P2W919710AA', '', '43', '7. Dàn nóng Transit (sedanviet) | P2W9-19710-AA', '7-dan-nong-transit-sedanviet-p2w9-19710-aa', '<h2>Tổng quan về Dàn nóng Transit</h2>
