INSERT INTO products VALUES ('5003', '1', '9520064JB1', '95200-64JB1 / 9520064JB1', '', '22', '7. Lốc điều hòa Vitara (sedanviet) | 95200-64JB1', '7-loc-dieu-hoa-vitara-sedanviet-95200-64jb1', '<h2>Tổng quan về Lốc điều hòa Vitara</h2>
