INSERT INTO products VALUES ('5260', '1', '8837030020', '88370-30020 / 8837030020', '', '22', '7. Lốc điều hòa Camry (sedanviet) | 88370-30020', '7-loc-dieu-hoa-camry-sedanviet-88370-30020', '<h2>Tổng quan về Lốc điều hòa Camry</h2>
