INSERT INTO products VALUES ('6833', '1', 'TCA-LIVE-48-16', 'SP00018', '', '48', 'BỘ ĐẦU LỐC ALTIS | SP00018', 'bo-dau-loc-altis-sp00018', '<h2>1. Mô Tả Sản Phẩm BỘ ĐẦU LỐC ALTIS</h2> <div style="text-align: center; margin: 20px 0;"><img style="max-width: 100%; height: 324px; border-radius: 10px; box-shadow: rgba(0, 0, 0, 0.08) 0px 4px 12px;" src="../../../uploads/products/bo-dau-loc-altis_phu_tung_oto_thanh_cong_auto.jpg" alt="BỘ ĐẦU LỐC ALTIS" width="324"></div> <div style="margin: 20px 0px; text-align: left;">Bộ đầu lốc Altis (bao gồm puly, cuộn từ và mặt hít) là phụ tùng thay thế chuẩn thông số kỹ thuật hệ thống điều hòa xe Altis. Được chế tạo từ vật liệu chịu nhiệt và ma sát cao, sản phẩm giúp lốc lạnh đóng ngắt chính xác, vận hành trơn tru, hạn chế tiếng ồn khoang máy và đảm bảo duy trì nhiệt độ lạnh sâu bền bỉ.</div> <h2>2. Thiết Kế Kỹ Thuật & Tương Thích Dòng Xe</h2> <p>Linh kiện <strong>BỘ ĐẦU LỐC ALTIS</strong> đóng vai trò vô cùng quan trọng trong việc duy trì nhiệt độ cabin lý tưởng, giúp tối ưu áp suất gas và dòng khí làm mát/sưởi ấm. Được sản xuất trên dây chuyền công nghệ hiện đại, sản phẩm chịu được áp suất làm việc lớn và biến thiên nhiệt độ khắc nghiệt trong khoang động cơ xe <strong>Altis</strong>.</p> <ul> <li><strong>Lắp đặt chuẩn xác:</strong> Đúng kích thước và chân bắt theo thiết kế nguyên bản của dòng xe Altis.</li> <li><strong>Vận hành êm ái:</strong> Giảm thiểu tiếng ồn và độ rung lắc khi hệ thống điều hòa hoạt động.</li> <li><strong>Tiết kiệm nhiên liệu:</strong> Giúp lốc lạnh và quạt gió vận hành tối ưu, giảm tải động cơ ô tô.</li> </ul> <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 12px; padding: 20px 24px; margin-top: 28px;"> <h4 style="margin: 0 0 12px; font-size: 15px; font-weight: bold; color: #1a3258;">Cooling Systems- Chuỗi Dịch vụ & Phụ tùng Điều Hòa Ô Tô Chuyên Nghiệp.</h4> <p style="margin: 0 0 8px; font-size: 13.5px; color: #475569;">• Hotline & Zalo tư vấn: <strong style="color: #1a3258;">0705 070 526</strong></p> <p style="margin: 0 0 8px; font-size: 13.5px; color: #475569;">• Email hỗ trợ: <strong style="color: #1a3258;">hotrokhachhang@autopartsvietnam.com</strong></p> <p style="margin: 0; font-size: 13.5px; color: #475569;">• Website chính thức: <a style="color: #1a3258; font-weight: bold;" href="../../../" target="_blank" rel="noopener">https://coolingsystems.vn</a></p> </div>', NULL, '675000', '750000', '999', '0', NULL, NULL, NULL, NULL, 'published', NULL, '0', '0', '0', '0', '0', '4', '0.0', '0', '6', NULL, NULL, NULL, '2026-08-02 19:09:10', '2026-08-12 21:44:20', NULL, 'BỘ ĐẦU LỐC ALTIS Bộ đầu lốc Altis (bao gồm puly, cuộn từ và mặt hít) là phụ tùng thay thế chuẩn thông số kỹ thuật hệ thống điều hòa xe Altis....', 'bộ đầu lốc altis | sp00018', NULL, NULL, '1', '0', '0', '10', 'SP00018', '5', '1000', '<ul> <li><strong>Đạt chuẩn chất lượng OEM:</strong> Sản phẩm BỘ ĐẦU LỐC ALTIS đáp ứng nghiêm ngặt các tiêu chuẩn kỹ thuật của nhà sản xuất phụ tùng ô tô .</li> <li><strong>Vật liệu cao cấp:</strong> Chế tạo từ hợp kim nhôm chịu lực, lõi đồng truyền nhiệt tốt và hợp chất cao su tổng hợp chống lão hóa.</li> <li><strong>Độ tương thích hoàn hảo:</strong> Tương thích chính xác với hệ thống điều hòa xe <strong>Altis</strong>, không cần gia công hay chỉnh sửa khi thay thế.</li> <li><strong>Độ bền & An toàn:</strong> Kháng ăn mòn hóa chất, hoạt động ổn định và an toàn tuyệt đối trong thời gian dài.</li> </ul>', '<table style="width:100%;border-collapse:collapse;margin-top:10px;margin-bottom:15px;border:1px solid #e2e8f0;"> <tbody> <tr style="background-color:#f8fafc;"> <td style="padding:10px 14px;border:1px solid #e2e8f0;font-weight:bold;width:35%;">Tên sản phẩm</td> <td style="padding:10px 14px;border:1px solid #e2e8f0;">BỘ ĐẦU LỐC ALTIS</td> </tr> <tr> <td style="padding:10px 14px;border:1px solid #e2e8f0;font-weight:bold;">Mã OEM chính</td> <td style="padding:10px 14px;border:1px solid #e2e8f0;"><strong style="color:#1a3258;">SP00018</strong></td> </tr> <tr 